import type { App, TFile } from "obsidian";

export const buildObsidianUrl = (
  vaultName: string,
  filePath: string,
): string =>
  `obsidian://open?vault=${encodeURIComponent(vaultName)}&file=${encodeURIComponent(filePath)}`;

/**
 * Obsidian's editor drop handler only reads `text/html` and OS files, so a link
 * dragged from our own UI is inserted by CodeMirror straight from `text/plain`.
 * The link therefore has to be formatted here, at dragstart.
 */
export const setFileDragData = ({
  dataTransfer,
  app,
  file,
  sourcePath,
}: {
  dataTransfer: DataTransfer | null;
  app: App;
  file: TFile;
  sourcePath: string;
}): void => {
  if (!dataTransfer) return;

  // generateMarkdownLink is what honours the vault's link-format setting.
  dataTransfer.setData(
    "text/plain",
    app.fileManager.generateMarkdownLink(file, sourcePath),
  );
  // The canvas reads uri-list, so it still gets a resolvable obsidian:// URL.
  dataTransfer.setData(
    "text/uri-list",
    buildObsidianUrl(app.vault.getName(), file.path),
  );
};

