import { describe, expect, it, vi } from "vitest";
import type { App, TFile } from "obsidian";
import { buildObsidianUrl, setFileDragData } from "~/utils/fileDragData";

const makeDataTransfer = () => {
  const data = new Map<string, string>();
  return {
    data,
    setData: (format: string, value: string) => void data.set(format, value),
  };
};

const makeApp = (generateMarkdownLink: ReturnType<typeof vi.fn>) =>
  ({
    fileManager: { generateMarkdownLink },
    vault: { getName: () => "My Vault" },
  }) as unknown as App;

const file = { path: "notes/Claim A.md" } as TFile;

describe("buildObsidianUrl", () => {
  it("encodes the vault name and the file path", () => {
    expect(buildObsidianUrl("My Vault", "notes/Claim A.md")).toBe(
      "obsidian://open?vault=My%20Vault&file=notes%2FClaim%20A.md",
    );
  });
});

describe("setFileDragData", () => {
  it("puts the generated link in text/plain and the url in text/uri-list", () => {
    const generateMarkdownLink = vi.fn().mockReturnValue("[[Claim A]]");
    const dataTransfer = makeDataTransfer();

    setFileDragData({
      dataTransfer: dataTransfer as unknown as DataTransfer,
      app: makeApp(generateMarkdownLink),
      file,
      sourcePath: "notes/Question B.md",
    });

    expect(dataTransfer.data.get("text/plain")).toBe("[[Claim A]]");
    expect(dataTransfer.data.get("text/uri-list")).toBe(
      "obsidian://open?vault=My%20Vault&file=notes%2FClaim%20A.md",
    );
  });

  it("formats the link against the destination note, not the dragged file", () => {
    const generateMarkdownLink = vi.fn().mockReturnValue("[Claim A](Claim%20A.md)");
    setFileDragData({
      dataTransfer: makeDataTransfer() as unknown as DataTransfer,
      app: makeApp(generateMarkdownLink),
      file,
      sourcePath: "notes/Question B.md",
    });

    expect(generateMarkdownLink).toHaveBeenCalledWith(
      file,
      "notes/Question B.md",
    );
  });

  it("does nothing when the event carries no dataTransfer", () => {
    const generateMarkdownLink = vi.fn();

    expect(() =>
      setFileDragData({
        dataTransfer: null,
        app: makeApp(generateMarkdownLink),
        file,
        sourcePath: "notes/Question B.md",
      }),
    ).not.toThrow();
    expect(generateMarkdownLink).not.toHaveBeenCalled();
  });
});

