// ENG-1947: assert the Discourse Context drag payload under both vault link formats.
import { resolveWebSocket } from "/Users/trang.doan/.claude/skills/dg-obsidian-cdp-verify/scripts/websocket.mjs";

const PORT = 9222;
const ROOT = "/Users/trang.doan/Documents/testVault";

const open = async (url) => {
  const WebSocket = await resolveWebSocket();
  const ws = new WebSocket(url);
  let id = 0;
  const pending = new Map();
  await new Promise((res, rej) => {
    ws.addEventListener("open", res, { once: true });
    ws.addEventListener("error", (e) => rej(e.error ?? new Error("ws")), { once: true });
  });
  ws.addEventListener("message", (ev) => {
    const m = JSON.parse(ev.data.toString());
    const p = m.id && pending.get(m.id);
    if (!p) return;
    pending.delete(m.id);
    m.error ? p.reject(new Error(JSON.stringify(m.error))) : p.resolve(m.result);
  });
  const send = (method, params = {}) =>
    new Promise((resolve, reject) => {
      const msgId = ++id;
      pending.set(msgId, { resolve, reject });
      ws.send(JSON.stringify({ id: msgId, method, params }));
    });
  return {
    send,
    close: () => ws.close(),
    evaluate: async (expr) => {
      const r = await send("Runtime.evaluate", {
        expression: `(() => { ${expr.includes("return") ? expr : `return ${expr}`} })()`,
        awaitPromise: true,
        returnByValue: true,
      });
      if (r.exceptionDetails) throw new Error(r.exceptionDetails.exception?.description ?? "eval failed");
      return r.result.value;
    },
  };
};

const targets = (await (await fetch(`http://127.0.0.1:${PORT}/json/list`)).json()).filter(
  (t) => t.type === "page" && !t.url.startsWith("devtools://"),
);

// Pick the testVault window that owns a serializable layout — not a popout.
let client = null;
for (const t of targets) {
  const c = await open(t.webSocketDebuggerUrl);
  const ok = await c
    .evaluate(
      `return (typeof app !== "undefined" && app.vault?.adapter?.basePath === ${JSON.stringify(ROOT)} && !!app.workspace.getLayout?.())`,
    )
    .catch(() => false);
  if (ok === true) {
    client = c;
    console.log("attached:", t.title);
    break;
  }
  c.close();
}
if (!client) throw new Error("no usable testVault target");

const setFormat = async (useMarkdownLinks) =>
  client.evaluate(
    `app.vault.setConfig("useMarkdownLinks", ${useMarkdownLinks}); return app.vault.getConfig("useMarkdownLinks");`,
  );

// Fire a real dragstart on the first Discourse Context entry and capture the payload.
const dragPayload = async () =>
  client.evaluate(`
    return (() => {
      const leaf = app.workspace.getLeavesOfType("discourse-context")[0];
      if (!leaf) return { error: "discourse context view not open" };
      const anchors = Array.from(
        leaf.view.containerEl.querySelectorAll(".current-relationships a, a.text-accent-text"),
      ).filter((a) => a.draggable);
      if (!anchors.length) return { error: "no draggable entry anchors found" };
      const a = anchors[0];
      const dt = new DataTransfer();
      const ev = new DragEvent("dragstart", { bubbles: true, cancelable: true, dataTransfer: dt });
      a.dispatchEvent(ev);
      return {
        entry: a.textContent,
        plain: dt.getData("text/plain"),
        uriList: dt.getData("text/uri-list"),
      };
    })();
  `);

const original = await client.evaluate(`return app.vault.getConfig("useMarkdownLinks")`);
const activeFile = await client.evaluate(`return app.workspace.getActiveFile()?.path ?? null`);
console.log("active file:", activeFile, "| original useMarkdownLinks:", original);

const results = {};
try {
  for (const [label, flag] of [["wikilink", false], ["markdown", true]]) {
    await setFormat(flag);
    results[label] = await dragPayload();
  }
} finally {
  await setFormat(original);
}
console.log(JSON.stringify(results, null, 2));
console.log("restored useMarkdownLinks:", await client.evaluate(`return app.vault.getConfig("useMarkdownLinks")`));
client.close();

