// ENG-1947: real native drag via CDP drag interception, into the live editor.
// Captures the actual drag payload Chromium builds (incl. text/html) and the inserted text.
import { resolveWebSocket } from "/Users/trang.doan/.claude/skills/dg-obsidian-cdp-verify/scripts/websocket.mjs";

const ROOT = "/Users/trang.doan/Documents/testVault";
const PLUGIN = "@discourse-graph/obsidian";
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

const open = async (url) => {
  const WebSocket = await resolveWebSocket();
  const ws = new WebSocket(url);
  let id = 0;
  const pending = new Map();
  const listeners = new Map();
  await new Promise((res, rej) => {
    ws.addEventListener("open", res, { once: true });
    ws.addEventListener("error", (e) => rej(e.error ?? new Error("ws")), { once: true });
  });
  ws.addEventListener("message", (ev) => {
    const m = JSON.parse(ev.data.toString());
    if (m.method) {
      const l = listeners.get(m.method);
      if (l) l(m.params);
      return;
    }
    const p = m.id && pending.get(m.id);
    if (!p) return;
    pending.delete(m.id);
    m.error ? p.reject(new Error(JSON.stringify(m.error))) : p.resolve(m.result);
  });
  const send = (method, params = {}) =>
    new Promise((resolve, reject) => {
      const i = ++id;
      pending.set(i, { resolve, reject });
      ws.send(JSON.stringify({ id: i, method, params }));
    });
  return {
    send,
    close: () => ws.close(),
    once: (method) => new Promise((resolve) => listeners.set(method, resolve)),
    evaluate: async (expr) => {
      const r = await send("Runtime.evaluate", {
        expression: `(async () => { ${expr} })()`,
        awaitPromise: true,
        returnByValue: true,
      });
      if (r.exceptionDetails)
        throw new Error(r.exceptionDetails.exception?.description ?? "eval failed");
      return r.result.value;
    },
  };
};

const targets = (await (await fetch("http://127.0.0.1:9222/json/list")).json()).filter(
  (t) => t.type === "page" && !t.url.startsWith("devtools://"),
);
let client = null;
for (const t of targets) {
  const c = await open(t.webSocketDebuggerUrl);
  const ok = await c
    .evaluate(`return typeof app !== "undefined" && app.vault?.adapter?.basePath === ${JSON.stringify(ROOT)};`)
    .catch(() => false);
  if (ok === true) { client = c; console.log("attached:", t.title.slice(0, 60)); break; }
  c.close();
}
if (!client) throw new Error("no testVault target");

// Open a node with a live (non-orphaned) relation, and the context view.
const setup = JSON.parse(await client.evaluate(`
  const raw = await app.vault.adapter.read("relations.json");
  const rels = Object.values(JSON.parse(raw).relations || {});
  const live = new Set((app.plugins.plugins[${JSON.stringify(PLUGIN)}].settings.relationTypes || []).map(t => t.id));
  const byInstance = new Map();
  for (const f of app.vault.getMarkdownFiles()) {
    const id = app.metadataCache.getFileCache(f)?.frontmatter?.nodeInstanceId;
    if (id) byInstance.set(id, f);
  }
  if (app.workspace.getLeavesOfType("discourse-context-view").length === 0) {
    await app.workspace.getRightLeaf(false).setViewState({ type: "discourse-context-view", active: true });
  }
  for (const r of rels) {
    if (!live.has(r.type)) continue;
    const src = byInstance.get(r.source);
    if (!src || !byInstance.get(r.destination)) continue;
    const leaf = app.workspace.getLeavesOfType("markdown")[0] || app.workspace.getLeaf("tab");
    await leaf.openFile(src);
    app.workspace.setActiveLeaf(leaf, { focus: true });
    return JSON.stringify({ path: src.path, original: await app.vault.read(src) });
  }
  return JSON.stringify({ error: "no live relation" });
`));
if (setup.error) throw new Error(setup.error);
console.log("note:", setup.path);
await sleep(3500);

const rects = JSON.parse(await client.evaluate(`
  const leaf = app.workspace.getLeavesOfType("discourse-context-view")[0];
  const a = Array.from(leaf.view.containerEl.querySelectorAll("a")).find(x => x.draggable);
  if (!a) return JSON.stringify({ error: "no draggable anchor" });
  const ar = a.getBoundingClientRect();
  const cm = app.workspace.getLeavesOfType("markdown")[0].view.containerEl.querySelector(".cm-content");
  const cr = cm.getBoundingClientRect();
  return JSON.stringify({
    entry: a.textContent,
    from: { x: ar.left + ar.width / 2, y: ar.top + ar.height / 2 },
    to:   { x: cr.left + 60, y: cr.top + 12 },
  });
`));
if (rects.error) throw new Error(rects.error);
console.log("dragging:", rects.entry);

const runDrag = async (label) => {
  await client.send("Input.setInterceptDrags", { enabled: true });
  const intercepted = client.once("Input.dragIntercepted");
  await client.send("Input.dispatchMouseEvent", {
    type: "mousePressed", x: rects.from.x, y: rects.from.y, button: "left", clickCount: 1, buttons: 1,
  });
  for (let i = 1; i <= 6; i++) {
    await client.send("Input.dispatchMouseEvent", {
      type: "mouseMoved",
      x: rects.from.x + i * 12, y: rects.from.y + i * 6, button: "left", buttons: 1,
    });
    await sleep(40);
  }
  const { data } = await Promise.race([
    intercepted,
    sleep(6000).then(() => ({ data: null })),
  ]);
  if (!data) throw new Error("drag was never intercepted");

  console.log(`\n[${label}] real drag payload:`);
  for (const it of data.items) console.log("   ", it.mimeType, "=>", JSON.stringify(it.data));

  for (const type of ["dragEnter", "dragOver", "drop"]) {
    await client.send("Input.dispatchDragEvent", {
      type, x: rects.to.x, y: rects.to.y, data, modifiers: 0,
    });
    await sleep(120);
  }
  await client.send("Input.dispatchMouseEvent", {
    type: "mouseReleased", x: rects.to.x, y: rects.to.y, button: "left", clickCount: 1,
  });
  await client.send("Input.setInterceptDrags", { enabled: false });
  await sleep(700);

  const inserted = await client.evaluate(`
    const ed = app.workspace.getLeavesOfType("markdown")[0].view.editor;
    const body = ed.getValue().split("---").slice(2).join("---");
    return body.trim().split("\\n").filter(l => l.trim()).slice(0, 3).join(" | ");
  `);
  // Put the note back exactly as we found it.
  await client.evaluate(`
    const f = app.vault.getAbstractFileByPath(${JSON.stringify(setup.path)});
    await app.vault.modify(f, ${JSON.stringify(setup.original)});
    return true;
  `);
  return inserted;
};

const original = await client.evaluate(`return app.vault.getConfig("useMarkdownLinks");`);
try {
  for (const [label, flag] of [["wikilink", false], ["markdown", true]]) {
    await client.evaluate(`app.vault.setConfig("useMarkdownLinks", ${flag}); return true;`);
    await sleep(400);
    console.log(`[${label}] inserted:`, await runDrag(label));
  }
} finally {
  await client.evaluate(`app.vault.setConfig("useMarkdownLinks", ${original}); return true;`);
  await client.send("Input.setInterceptDrags", { enabled: false }).catch(() => {});
  console.log("\nrestored useMarkdownLinks:", await client.evaluate(`return app.vault.getConfig("useMarkdownLinks");`));
}
client.close();

