const inserted = await client.evaluate(`
  const ed = app.workspace.getLeavesOfType("markdown")[0].view.editor;
  const before = ${JSON.stringify(setup.original)};
  const after = ed.getValue();
  let i = 0;
  while (i < before.length && before[i] === after[i]) i++;
  let j = 0;
  while (j < before.length - i && before[before.length - 1 - j] === after[after.length - 1 - j]) j++;
  return after.slice(i, after.length - j);
`);
